using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation.Infrastructure;

/// <summary>
/// Shared test fixture that boots the Aspire AppHost and provides
/// an <see cref="IChatClient"/> for evaluations.
/// </summary>
public sealed class EvaluationFixture : IAsyncDisposable
{
    private DistributedApplication? _app;
    private IChatClient? _chatClient;
    private ReportingConfiguration? _reportingConfig;

    public IChatClient ChatClient => _chatClient ?? throw new InvalidOperationException("Not initialized");
    public ReportingConfiguration ReportingConfiguration => _reportingConfig ?? throw new InvalidOperationException("Not initialized");

    public async Task InitializeAsync()
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = CreateReportingConfiguration();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Directory.GetCurrentDirectory(),
            "evaluation-report");

        return DiskBasedReportingConfiguration.Create(storageRootPath: path);
    }

    public async ValueTask DisposeAsync()
    {
        if (_chatClient is IAsyncDisposable disposableClient)
            await disposableClient.DisposeAsync();

        if (_app is not null)
            await _app.DisposeAsync();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using MyApp.Evaluation.Infrastructure;

namespace MyApp.Evaluation;

[TestClass]
public sealed class ChatEvaluationTests
{
    private static readonly EvaluationFixture s_fixture = new();

    [ClassInitialize]
    public static async Task Setup(TestContext _) => await s_fixture.InitializeAsync();

    [ClassCleanup]
    public static async Task Teardown() => await s_fixture.DisposeAsync();

    private static IEnumerable<IEvaluator> GetEvaluators()
    {
        yield return new CoherenceEvaluator();
        yield return new RelevanceEvaluator();
        yield return new FluencyEvaluator();
    }

    [TestMethod]
    public async Task Greeting_IsCoherentAndRelevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await s_fixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evaluators = GetEvaluators().ToList();
        var results = await evaluators.EvaluateAsync(messages, s_fixture.ReportingConfiguration);

        foreach (var metric in results.Metrics)
        {
            Assert.IsTrue(
                metric.Value is NumericMetric { InterpretedValue: >= EvaluationRating.Good },
                $"Metric '{metric.Key}' did not meet the quality threshold.");
        }
    }

    [TestMethod]
    public async Task FollowUp_MaintainsContext()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var response1 = await s_fixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var response2 = await s_fixture.ChatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        var evaluators = GetEvaluators().ToList();
        var results = await evaluators.EvaluateAsync(messages, s_fixture.ReportingConfiguration);

        Assert.IsTrue(
            response2.Text?.Contains("Alice", StringComparison.OrdinalIgnoreCase) == true,
            "The model should recall the user's name from context.");

        foreach (var metric in results.Metrics)
        {
            Assert.IsTrue(
                metric.Value is NumericMetric { InterpretedValue: >= EvaluationRating.Good },
                $"Metric '{metric.Key}' did not meet the quality threshold.");
        }
    }
}

