/// an <see cref="IChatClient"/> for evaluations.
/// </summary>
public sealed class EvaluationFixture : IAsyncDisposable
{
    private DistributedApplication? _app;
    private IChatClient? _chatClient;
    private ReportingConfiguration? _reportingConfig;

    public IChatClient ChatClient => _chatClient ?? throw new InvalidOperationException("Not initialized");
    public ReportingConfiguration ReportingConfiguration => _reportingConfig ?? throw new InvalidOperationException("Not initialized");

    public async Task InitializeAsync()
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        _app = await appHost.BuildAsync();
        await _app.StartAsync();

        var connectionString = await _app.GetConnectionStringAsync("openai");
        _chatClient = CreateChatClient(connectionString!);
        _reportingConfig = CreateReportingConfiguration();
    }

    private static IChatClient CreateChatClient(string connectionString)
    {
        // Parse the Aspire-style connection string for Azure OpenAI
        var parts = connectionString.Split(';')
            .Select(p => p.Split('=', 2))
            .Where(p => p.Length == 2)
            .ToDictionary(p => p[0], p => p[1], StringComparer.OrdinalIgnoreCase);

        var endpoint = parts.GetValueOrDefault("Endpoint")
            ?? throw new InvalidOperationException("Connection string missing Endpoint");

        var client = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential());

        return client.GetChatClient("chat").AsIChatClient();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Directory.GetCurrentDirectory(),
            "evaluation-report");

        return DiskBasedReportingConfiguration.Create(storageRootPath: path);
    }

    public async ValueTask DisposeAsync()
    {
        if (_chatClient is IAsyncDisposable disposableClient)
            await disposableClient.DisposeAsync();

        if (_app is not null)
            await _app.DisposeAsync();
    }
}

