 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.AI.Evaluation;
 using Microsoft.Extensions.AI.Evaluation.Reporting;
 using Microsoft.VisualStudio.TestTools.UnitTesting;
 using MyApp.Evaluation.Infrastructure;

 namespace MyApp.Evaluation;

 [TestClass]
 public sealed class ChatEvaluationTests
 {
     private static readonly EvaluationFixture s_fixture = new();

     [ClassInitialize]
     public static async Task Setup(TestContext _) => await s_fixture.InitializeAsync();

     [ClassCleanup]
     public static async Task Teardown() => await s_fixture.DisposeAsync();

     [TestMethod]
     public async Task Greeting_IsCoherentAndRelevant()
     {
         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "Hello, how can you help me today?")
         };

         var response = await s_fixture.ChatClient.GetResponseAsync(messages);

         await using var scenarioRun = await s_fixture.ReportingConfiguration
             .CreateScenarioRunAsync(scenarioName: nameof(Greeting_IsCoherentAndRelevant));

         var result = await scenarioRun.EvaluateAsync(messages, response);

         foreach (var metric in result.Metrics)
         {
             Assert.IsTrue(
